    y = Polynomial.variable(2, 1)
    expression = (x-y)*(x+y+16)
    q, remainder = expression.divided_remainder((x-y,))
    assert not remainder and q[0] == x+y+16
    assert expression.eval((1, 9)) == (1-9)*(1+9+16)
    assert expression.derivative(0).eval((1, 9)) == 2*1+16

